    private void sharingChecks(Context ctx,DbHelper db,Contact sample)throws Exception{
        String[] extensions={".xlsx",".csv",".vcf",".zip"},types={"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet","text/csv","text/vcard","application/zip"};
        File previous=null;byte[] previousBytes=null;
        for(int i=0;i<extensions.length;i++){stage("attachment "+extensions[i]);
            File file=i==3?BackupManager.createBackup(ctx,Collections.singletonList(sample)):ExportShare.newFile(ctx,"내보내기_검사",extensions[i]);
            if(i==0)DataExchange.writeXlsx(file,Collections.singletonList(sample));if(i==1)DataExchange.writeCsv(file,Collections.singletonList(sample));if(i==2)DataExchange.writeVcard(file,Collections.singletonList(sample));
            Intent intent=ExportShare.sendIntent(ctx,file);android.net.Uri uri=intent.getParcelableExtra(Intent.EXTRA_STREAM);check(Intent.ACTION_SEND.equals(intent.getAction())&&types[i].equals(intent.getType()),"share type "+extensions[i]);check("content".equals(uri.getScheme()),"content attachment URI");check(intent.getClipData()!=null&&intent.getClipData().getItemAt(0).getUri().equals(uri),"ClipData URI grant");check((intent.getFlags()&Intent.FLAG_GRANT_READ_URI_PERMISSION)!=0&&(intent.getFlags()&Intent.FLAG_GRANT_WRITE_URI_PERMISSION)==0,"read-only grant");
            try(android.database.Cursor cursor=ctx.getContentResolver().query(uri,new String[]{android.provider.OpenableColumns.SIZE,android.provider.OpenableColumns.DISPLAY_NAME},null,null,null)){check(cursor!=null&&cursor.moveToFirst()&&cursor.getLong(0)==file.length()&&cursor.getString(1).equals(file.getName()),"receiver filename and size projection");}
            byte[] expected=bytes(new FileInputStream(file));check(Arrays.equals(expected,bytes(ctx.getContentResolver().openInputStream(uri))),"attachment is readable");boolean denied=false;try(OutputStream out=ctx.getContentResolver().openOutputStream(uri,"w")){}catch(Exception e){denied=true;}check(denied&&file.length()==expected.length,"exports reject writes");
            java.util.concurrent.CountDownLatch received=new java.util.concurrent.CountDownLatch(1);final Intent[] report={null};BroadcastReceiver receiver=new BroadcastReceiver(){public void onReceive(Context c,Intent message){report[0]=message;received.countDown();}};IntentFilter filter=new IntentFilter("com.lsi.businesscard.TEST_ATTACHMENT_READ");if(android.os.Build.VERSION.SDK_INT>=33)ctx.registerReceiver(receiver,filter,Context.RECEIVER_EXPORTED);else ctx.registerReceiver(receiver,filter);try{ctx.startActivity(new Intent(intent).setComponent(new ComponentName("com.lsi.businesscard.test","com.lsi.businesscard.AttachmentReceiver")).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));check(received.await(15,java.util.concurrent.TimeUnit.SECONDS),"external receiver timeout");check(report[0].getStringExtra("error")==null,"receiver error: "+report[0].getStringExtra("error"));check(report[0].getIntExtra("uid",-1)!=android.os.Process.myUid(),"receiver has separate UID");check(Arrays.equals(java.security.MessageDigest.getInstance("SHA-256").digest(expected),report[0].getByteArrayExtra("digest")),"external receiver reads attachment "+extensions[i]);check(types[i].equals(report[0].getStringExtra("mime"))&&file.getName().equals(report[0].getStringExtra("name")),"external receiver MIME and filename");}finally{ctx.unregisterReceiver(receiver);}
            if(i==3){try(java.util.zip.ZipFile zip=new java.util.zip.ZipFile(file)){org.json.JSONObject json=new org.json.JSONObject(new String(bytes(zip.getInputStream(zip.getEntry("contacts.json"))),"UTF-8"));check(json.getJSONArray("contacts").length()==1,"selected ZIP contains only selected card");String entry=json.getJSONArray("contacts").getJSONObject(0).getString("image_front");check(zip.getEntry(entry)!=null,"selected ZIP includes card photo");}}
            if(previous!=null)check(Arrays.equals(previousBytes,bytes(new FileInputStream(previous))),"new export preserves earlier attachment");previous=file;previousBytes=expected;
        }
        boolean denied=false;try{CardFileProvider.uriFor(ctx,ctx.getDatabasePath(DbHelper.DB_NAME));}catch(SecurityException e){denied=true;}check(denied,"private DB is not exposed");
        android.net.Uri bad=new android.net.Uri.Builder().scheme("content").authority(CardFileProvider.AUTHORITY).appendPath("exports").appendPath("../contacts.db").build();denied=false;try(InputStream input=ctx.getContentResolver().openInputStream(bad)){}catch(Exception e){denied=true;}check(denied,"URI traversal is rejected");
        File camera=CardFileProvider.newCameraFile(ctx,"provider_check");try(OutputStream out=ctx.getContentResolver().openOutputStream(CardFileProvider.uriFor(ctx,camera),"w")){out.write(new byte[]{1,2,3});}check(camera.length()==3,"camera remains writable");camera.delete();
    }
    private byte[] bytes(InputStream input)throws Exception{if(input==null)throw new IOException("null stream");try(InputStream in=input;ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] buffer=new byte[8192];int n;while((n=in.read(buffer))!=-1)out.write(buffer,0,n);return out.toByteArray();}}
    private void awaitFocus(Activity activity){for(int i=0;i<50;i++){final boolean[] focused={false};runOnMainSync(()->focused[0]=activity.hasWindowFocus());if(focused[0])return;android.os.SystemClock.sleep(100);waitForIdleSync();}android.view.accessibility.AccessibilityNodeInfo active=getUiAutomation().getRootInActiveWindow();throw new AssertionError("Activity did not acquire focus: "+activity.getClass().getSimpleName()+" active="+(active==null?"none":active.getPackageName()));}
    private void injectTouch(long down,long time,int action,float x,float y){android.view.MotionEvent event=android.view.MotionEvent.obtain(down,time,action,x,y,0);event.setSource(android.view.InputDevice.SOURCE_TOUCHSCREEN);try{check(getUiAutomation().injectInputEvent(event,true),"touch event "+action);}finally{event.recycle();}}
    private void back(){long time=android.os.SystemClock.uptimeMillis();check(getUiAutomation().injectInputEvent(new KeyEvent(time,time,KeyEvent.ACTION_DOWN,KeyEvent.KEYCODE_BACK,0),true),"back key down");check(getUiAutomation().injectInputEvent(new KeyEvent(time,android.os.SystemClock.uptimeMillis(),KeyEvent.ACTION_UP,KeyEvent.KEYCODE_BACK,0),true),"back key up");}
    private void activeClick(String text)throws Exception{android.os.SystemClock.sleep(250);android.view.accessibility.AccessibilityNodeInfo root=getUiAutomation().getRootInActiveWindow();check(root!=null,"dialog accessibility root");for(android.view.accessibility.AccessibilityNodeInfo node:root.findAccessibilityNodeInfosByText(text)){if(node.getText()!=null&&text.equals(node.getText().toString())){android.view.accessibility.AccessibilityNodeInfo target=node;for(int depth=0;depth<4&&target!=null;depth++,target=target.getParent())if(target.isClickable()){check(target.performAction(android.view.accessibility.AccessibilityNodeInfo.ACTION_CLICK),"click "+text);return;}}}throw new AssertionError("missing menu action "+text);}
    private void injectOrientation(String path)throws Exception{byte[] data;try(InputStream in=new FileInputStream(path);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);data=out.toByteArray();}String hex="FFE1002245786966000049492A0008000000010012010300010000000600000000000000";try(OutputStream out=new FileOutputStream(path)){out.write(data,0,2);for(int i=0;i<hex.length();i+=2)out.write(Integer.parseInt(hex.substring(i,i+2),16));out.write(data,2,data.length-2);}}
    private void sortingAndLogoChecks(Context ctx)throws Exception{
        stage("all nine sort modes and logo migration");ctx.deleteDatabase(DbHelper.DB_NAME);DbHelper db=new DbHelper(ctx);
        Contact a=card(" 가나 "," 다가 ","010-1111-1111");a.put("created_at","2025-01-01 10:00:00");a.put("updated_at","2026-01-01 10:00:00");a.put("met_at","2025-03-01");a.id=db.insert(a);
        Contact b=card("다나","가가","010-2222-2222");b.put("created_at","2026/01/01 09:00:00");b.put("updated_at","2025-01-01 10:00:00");b.put("met_at","2024-03-01");b.id=db.insert(b);
        Contact c=card("나나","나가","010-3333-3333");c.put("created_at","2024-01-01T10:00:00");c.put("updated_at","2024-01-01");c.put("met_at","2026-03-01");c.id=db.insert(c);
        Contact empty=new Contact();empty.put("created_at","잘못된 날짜");empty.id=db.insert(empty);
        long[][] expected={{c.id,a.id,b.id,empty.id},{b.id,a.id,c.id,empty.id},{a.id,c.id,b.id,empty.id},{b.id,c.id,a.id,empty.id},{b.id,c.id,a.id,empty.id},{a.id,c.id,b.id,empty.id},{a.id,b.id,c.id,empty.id},{c.id,a.id,b.id,empty.id},{b.id,a.id,c.id,empty.id}};
        for(int mode=0;mode<9;mode++){List<Contact> actual=db.search("",false,"",mode);for(int i=0;i<4;i++)check(actual.get(i).id==expected[mode][i],"sort mode "+mode+" item "+i);}
        b.put("updated_at","2027-01-01");db.update(b);check(db.search("",false,"",1).get(0).id==b.id,"editing does not change input date order");check(db.search("",false,"",6).get(0).id==b.id,"editing moves modified sort only");check(!MainActivity.sameOrder(Arrays.asList(a,b),Arrays.asList(b,a)),"changed order resets scroll");check(!MainActivity.sameOrder(Arrays.asList(a,b),Arrays.asList(c,a,b)),"inserted card resets scroll");check(MainActivity.sameOrder(Arrays.asList(a,b),Arrays.asList(a,b)),"unchanged list preserves scroll");
        Contact logo=card("이용한","대구 협은행","011-810-8842");logo.put("email1","yhi1204@dgb.co.kr");logo.put("note3","[명함 OCR 원문]\n대구 협은행");logo.id=db.insert(logo);db.getWritableDatabase().setVersion(3);db.close();db=new DbHelper(ctx);Contact repaired=db.get(logo.id);check("대구은행".equals(repaired.get("company1")),"existing logo noise corrected on upgrade");check(repaired.get("note3").contains("대구 협은행")&&repaired.get("mobile1").equals("011-810-8842"),"logo migration retains original and phone");db.close();
    }
    private void screenshot(String name)throws Exception{android.os.SystemClock.sleep(350);waitForIdleSync();Bitmap b=getUiAutomation().takeScreenshot();if(b!=null)try(OutputStream out=new FileOutputStream(new File(getTargetContext().getExternalFilesDir(null),name+".png"))){b.compress(Bitmap.CompressFormat.PNG,100,out);}}
    private View findDescription(View view,String text){if(text.contentEquals(view.getContentDescription()==null?"":view.getContentDescription()))return view;if(view instanceof ViewGroup){ViewGroup g=(ViewGroup)view;for(int i=0;i<g.getChildCount();i++){View v=findDescription(g.getChildAt(i),text);if(v!=null)return v;}}return null;}
    private EditText findEdit(View view){if(view instanceof EditText)return (EditText)view;if(view instanceof ViewGroup){ViewGroup g=(ViewGroup)view;for(int i=0;i<g.getChildCount();i++){EditText v=findEdit(g.getChildAt(i));if(v!=null)return v;}}return null;}
    private ListView findList(View view){if(view instanceof ListView)return (ListView)view;if(view instanceof ViewGroup){ViewGroup g=(ViewGroup)view;for(int i=0;i<g.getChildCount();i++){ListView v=findList(g.getChildAt(i));if(v!=null)return v;}}return null;}
